@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--lime:#d8f36a;--ink:#0c100f;--glass:rgba(13,18,17,.78);--muted:#87928d;--line:rgba(221,235,219,.16);--red:#e95b4d}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101513;color:#f1f3eb;font-family:Manrope,Arial,sans-serif;touch-action:none;user-select:none;-webkit-user-select:none}#game{position:relative;width:100%;height:100%;overflow:hidden;background:#17201d}#scene{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 48%,transparent 34%,rgba(4,8,7,.2) 76%,rgba(4,8,7,.72) 130%),linear-gradient(180deg,rgba(8,12,11,.47),transparent 21%,transparent 67%,rgba(8,12,11,.65)}.topbar{position:absolute;z-index:2;left:0;right:0;top:0;height:72px;padding:0 36px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.09);background:linear-gradient(180deg,rgba(5,9,8,.52),transparent)}.brand{display:flex;align-items:center;gap:10px;font-size:15px;font-weight:800;letter-spacing:2px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;background:var(--lime);color:#182014;font:900 23px 'Barlow Condensed';clip-path:polygon(0 0,100% 0,100% 75%,76% 100%,0 100%)}.brand small{display:block;color:#9da69f;font:500 8px 'DM Mono';letter-spacing:2.5px;margin-top:3px}.mission{position:absolute;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:13px;font:500 10px 'DM Mono';letter-spacing:1.2px;color:#cad1c9}.mission i,.compass i{width:1px;height:14px;background:rgba(255,255,255,.24)}.live-dot,.pulse{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--lime);box-shadow:0 0 10px #d8f36a}.icon-btn{width:34px;height:34px;color:#dfe4dc;background:rgba(255,255,255,.07);border:1px solid var(--line);border-radius:50%;font-size:15px}.left-stack{position:absolute;top:94px;left:36px;width:210px}.raid-card{padding:13px 15px 14px;background:var(--glass);border:1px solid var(--line);backdrop-filter:blur(8px)}.card-label,.vital-head,.weapon-class,.extract-card small,.brief-stats span,.end-stats span{font:500 9px 'DM Mono';letter-spacing:1px;color:#a8b1a9}.card-label{display:flex;justify-content:space-between}.card-label span{color:var(--lime)}.raid-main{display:flex;align-items:center;gap:10px;padding:12px 0 10px}.raid-icon{font-size:20px;color:var(--lime)}.raid-main strong{display:block;font:700 17px 'Barlow Condensed';letter-spacing:1px}.raid-main small{display:block;margin-top:2px;color:#96a19a;font:9px 'DM Mono';letter-spacing:.5px}.progress-track,.health-track{height:3px;background:rgba(255,255,255,.13)}.progress-track i,.health-track i{display:block;width:0;height:100%;background:var(--lime);transition:width .25s}.threat{display:flex;gap:8px;align-items:center;margin-top:10px;color:#bbc2ba;font:9px 'DM Mono';letter-spacing:.7px}.threat-symbol{color:#e6a14e;font-size:14px}.threat b{color:#fff}.compass{position:absolute;top:91px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:11px;color:#f3f5ef;font:10px 'DM Mono';letter-spacing:1px;text-shadow:0 1px 5px #000}.compass>span:first-child,.compass>span:last-child{color:#aab2ab}.compass i{height:10px}.right-stack{position:absolute;right:36px;top:93px;display:flex;align-items:flex-end;flex-direction:column;gap:10px}.status-pill{display:flex;align-items:center;gap:8px;padding:8px 11px;background:var(--glass);border:1px solid var(--line);font:9px 'DM Mono';letter-spacing:.7px;color:#c3ccc4}.status-pill b{color:var(--lime);font-weight:500}.pulse{width:5px;height:5px}.kill-feed{display:flex;flex-direction:column;gap:5px}.kill-entry{font:9px 'DM Mono';letter-spacing:.6px;color:#dce1dc;background:rgba(11,15,14,.62);padding:6px 9px;border-left:2px solid var(--lime);animation:feed-in .25s}.kill-entry span{color:var(--lime)}@keyframes feed-in{from{transform:translateX(15px);opacity:0}to{transform:none;opacity:1}}.crosshair{position:absolute;left:50%;top:50%;width:24px;height:24px;transform:translate(-50%,-50%);pointer-events:none;transition:transform .12s}.crosshair i{position:absolute;background:rgba(240,246,233,.88);box-shadow:0 0 3px #000}.crosshair i:nth-child(1){width:1px;height:6px;top:0;left:11px}.crosshair i:nth-child(2){width:1px;height:6px;bottom:0;left:11px}.crosshair i:nth-child(3){width:6px;height:1px;left:0;top:11px}.crosshair i:nth-child(4){width:6px;height:1px;right:0;top:11px}.crosshair b{position:absolute;left:10px;top:10px;width:3px;height:3px;background:var(--lime);border-radius:50%}.hit-marker{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) scale(.5);font:25px Arial;color:#fff;opacity:0;pointer-events:none}.hit-marker.show{animation:hit .25s ease-out}@keyframes hit{0%{opacity:1;transform:translate(-50%,-50%) scale(.6)}100%{opacity:0;transform:translate(-50%,-50%) scale(1.25)}}.damage-flash{position:absolute;inset:0;box-shadow:inset 0 0 100px 35px rgba(207,39,26,0);pointer-events:none}.damage-flash.show{animation:damage .4s}@keyframes damage{0%{box-shadow:inset 0 0 100px 35px rgba(207,39,26,.55)}100%{box-shadow:inset 0 0 100px 35px rgba(207,39,26,0)}}.hud-bottom{position:absolute;left:36px;right:36px;bottom:24px;display:grid;grid-template-columns:1fr 250px 1fr;align-items:end;gap:20px}.vitals{width:220px;padding:12px 14px;background:var(--glass);border:1px solid var(--line);backdrop-filter:blur(8px)}.vital-head{display:flex;justify-content:space-between;margin-bottom:8px}.vital-head span:last-child{color:#f3f5ef;font-size:11px}.health-track{height:5px}.health-track i{background:var(--lime)}.vital-meta{display:flex;justify-content:space-between;margin-top:9px;color:#a6afa8;font:8px 'DM Mono';letter-spacing:.3px}.vital-meta b{color:#e6e9e3}.vital-meta .good{color:var(--lime)}.weapon-panel{background:rgba(10,14,13,.83);border:1px solid rgba(220,235,218,.22);padding:12px 15px 11px;backdrop-filter:blur(10px);box-shadow:0 10px 40px rgba(0,0,0,.2)}.weapon-top{display:flex;justify-content:space-between;align-items:flex-start}.weapon-class{font-size:8px;letter-spacing:.9px}.weapon-class i{font-style:normal;color:var(--lime);margin-left:5px}.weapon-top strong{display:block;margin-top:2px;font:700 20px 'Barlow Condensed';letter-spacing:1.2px}.fire-mode{margin-top:7px;padding:5px 7px;border:1px solid var(--line);color:#d8ded7;font:9px 'DM Mono'}.fire-mode span{color:var(--lime)}.ammo-row{display:flex;align-items:center;gap:10px;margin-top:9px;padding-top:8px;border-top:1px solid var(--line)}.ammo-count{white-space:nowrap}.ammo-count strong{font:600 26px 'Barlow Condensed';color:#f5f5ee}.ammo-count span{font:12px 'DM Mono';color:#87918b}.ammo-count span b{font-weight:400;color:#b9c1b9}.ammo-details{display:flex;flex:1;flex-direction:column;gap:4px;color:#d8ded7;font:8px 'DM Mono';letter-spacing:.6px}.ammo-details small{color:#7f8982;font-size:7px}.reload-ring{display:grid;place-items:center;width:24px;height:24px;border:1px solid #87918b;border-radius:50%;color:#e4e9e2;font:11px 'DM Mono'}.reload-ring.loading{border-color:var(--lime);color:var(--lime);animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.extract-card{justify-self:end;width:220px;display:flex;align-items:center;gap:10px;padding:11px 13px;background:var(--glass);border:1px solid var(--line);backdrop-filter:blur(8px)}.extract-icon{font-size:21px;color:var(--lime)}.extract-card div{display:flex;flex-direction:column;gap:4px;flex:1}.extract-card small{font-size:8px}.extract-card b{font:600 12px 'Barlow Condensed';letter-spacing:1px}.extract-key{padding:4px 6px;border:1px solid var(--line);font:10px 'DM Mono';color:#bac2bb}.controls-hint{position:absolute;bottom:130px;left:50%;transform:translateX(-50%);font:8px 'DM Mono';letter-spacing:1px;color:rgba(237,241,233,.65);white-space:nowrap}.controls-hint kbd{font:9px 'DM Mono';color:#e5e9e2;padding:4px 5px;border:1px solid rgba(255,255,255,.2);background:rgba(9,13,12,.55);margin:0 4px 0 10px}.reload-toast{position:absolute;top:59%;left:50%;transform:translate(-50%,-50%);font:700 15px 'Barlow Condensed';letter-spacing:3px;color:var(--lime);opacity:0;transition:opacity .15s;text-shadow:0 2px 6px #000}.reload-toast span{display:inline-block;animation:pulseText .7s infinite alternate}@keyframes pulseText{to{opacity:.3}}.reload-toast.show{opacity:1}.toast{position:absolute;top:24%;left:50%;transform:translateX(-50%);background:rgba(10,14,13,.88);border:1px solid var(--line);padding:10px 16px;color:#edf0e9;font:10px 'DM Mono';letter-spacing:1px;opacity:0;transition:opacity .25s}.toast.show{opacity:1}.overlay,.end-overlay{position:absolute;inset:0;z-index:4;background:linear-gradient(90deg,rgba(7,11,10,.94) 0%,rgba(7,11,10,.84) 42%,rgba(7,11,10,.16) 100%);display:flex;align-items:center;padding:7vw 10.5vw}.briefing{width:min(510px,55vw)}.brief-top{display:flex;align-items:center;justify-content:space-between;font:9px 'DM Mono';letter-spacing:1.3px}.eyebrow{color:var(--lime)}.eyebrow i{display:inline-block;width:6px;height:6px;background:var(--lime);border-radius:50%;margin-right:7px;box-shadow:0 0 8px var(--lime)}.brief-code{color:#9ba49d;font-size:8px}.briefing h1{font:800 clamp(55px,7vw,96px)/.82 'Barlow Condensed';letter-spacing:1px;margin:39px 0 23px}.briefing h1 em{font-style:normal;color:var(--lime)}.brief-copy{font-size:12px;line-height:1.8;color:#adb6ae;letter-spacing:.1px}.brief-stats{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:10px;margin:28px 0 24px;padding:14px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.brief-stats span{display:block;font-size:7px;margin-bottom:7px}.brief-stats b{font:600 10px 'DM Mono';letter-spacing:.3px}.brief-stats .threat-high{color:#ee715f}.start-btn{display:flex;justify-content:space-between;align-items:center;width:100%;max-width:330px;height:48px;padding:0 16px;background:var(--lime);border:0;color:#141a13;font:700 11px 'DM Mono';letter-spacing:1px;cursor:pointer;transition:background .15s,transform .15s;clip-path:polygon(0 0,100% 0,100% 75%,96% 100%,0 100%)}.start-btn:hover{background:#e8ff81;transform:translateY(-2px)}.start-btn b{font:20px Arial}.brief-foot{display:flex;gap:20px;margin-top:18px;color:#8f9991;font:7px 'DM Mono';letter-spacing:.6px}.brief-foot i{font-style:normal;color:var(--lime);margin:0 5px}.overlay-side{position:absolute;right:8%;bottom:16%;display:flex;align-items:center;gap:14px;color:rgba(231,237,228,.55);font:9px/1.8 'DM Mono';letter-spacing:1.7px}.side-line{height:45px;width:2px;background:var(--lime)}.end-overlay{z-index:5;justify-content:center;align-items:center;background:rgba(5,9,8,.82);backdrop-filter:blur(5px)}.end-overlay.hidden{display:none}.end-card{width:min(420px,90vw);padding:32px;background:rgba(13,18,17,.96);border:1px solid var(--line)}.end-card h2{font:800 52px 'Barlow Condensed';margin:12px 0 5px;letter-spacing:2px}.end-card p{color:#aab4ab;font-size:12px}.end-stats{display:flex;gap:40px;padding:20px 0;margin:20px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.end-stats span,.end-stats b{display:block}.end-stats b{font:700 24px 'Barlow Condensed';margin-top:5px}.mobile-controls{display:none}.touch-btn{border:1px solid rgba(255,255,255,.27);background:rgba(12,17,15,.55);color:#f0f3eb;backdrop-filter:blur(5px);border-radius:50%;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:2px;touch-action:none}.touch-btn small{font:7px 'DM Mono';letter-spacing:.5px}.fire-touch{background:rgba(216,243,106,.18);border-color:rgba(216,243,106,.65);color:var(--lime)}.fire-touch span{font-size:25px}.stick-zone{position:absolute;left:20px;bottom:22px;width:125px;height:125px;touch-action:none}.stick-base{position:absolute;inset:8px;border-radius:50%;background:rgba(230,239,229,.08);border:1px solid rgba(230,239,229,.25)}.stick-knob{position:absolute;width:44px;height:44px;left:50%;top:50%;transform:translate(-50%,-50%);border-radius:50%;background:rgba(222,239,214,.35);border:1px solid rgba(255,255,255,.45);box-shadow:0 2px 12px #0005}.mobile-actions{position:absolute;right:20px;bottom:20px;width:190px;height:180px}.mobile-actions .touch-btn{position:absolute;width:53px;height:53px}.aim-touch{top:0;left:13px}.fire-touch{top:42px;right:0;width:72px!important;height:72px!important}.reload-touch{bottom:0;left:13px}.swap-touch{bottom:16px;right:4px}.aim-touch.active{background:rgba(216,243,106,.3);color:var(--lime)}
@media(max-width:700px){.topbar{height:52px;padding:0 15px}.brand{font-size:12px;letter-spacing:1.5px}.brand-mark{width:28px;height:28px;font-size:19px}.brand small{font-size:6px}.mission{gap:7px;font-size:7px;letter-spacing:.5px}.mission i{height:10px}.sound-btn{width:29px;height:29px}.left-stack{top:66px;left:13px;width:145px}.raid-card{padding:9px 10px}.card-label{font-size:7px}.raid-main{padding:8px 0 7px;gap:7px}.raid-icon{font-size:16px}.raid-main strong{font-size:14px}.raid-main small{font-size:7px}.threat{font-size:7px;margin-top:7px}.compass{top:65px;font-size:8px;gap:7px}.right-stack{right:13px;top:66px}.status-pill{font-size:7px;padding:6px 8px}.kill-entry{font-size:7px;padding:5px 7px}.hud-bottom{left:12px;right:12px;bottom:calc(118px + env(safe-area-inset-bottom));display:flex;justify-content:center;gap:0}.weapon-panel{width:205px;padding:9px 11px}.weapon-top strong{font-size:17px}.weapon-class{font-size:7px}.ammo-count strong{font-size:22px}.vitals{position:absolute;left:0;bottom:-103px;width:150px;padding:8px 9px}.vital-head{font-size:7px}.vital-meta{font-size:6px}.extract-card{position:absolute;right:0;bottom:-103px;width:145px;padding:8px;gap:6px}.extract-card small{font-size:7px}.extract-card b{font-size:9px}.extract-icon{font-size:17px}.extract-key{font-size:8px;padding:3px 4px}.controls-hint{display:none}.mobile-controls{display:block}.overlay{padding:0 7vw;background:linear-gradient(90deg,rgba(7,11,10,.93),rgba(7,11,10,.58))}.briefing{width:100%;max-width:480px}.brief-top{font-size:7px}.brief-code{font-size:6px}.briefing h1{font-size:clamp(54px,15vw,86px);margin:27px 0 16px}.brief-copy{font-size:10px}.brief-stats{margin:18px 0;padding:11px 0;gap:5px}.brief-stats span{font-size:6px}.brief-stats b{font-size:8px}.brief-foot{flex-direction:column;gap:6px;font-size:6px}.overlay-side{display:none}.start-btn{height:44px}.mission #objective{display:none}.mission{left:52%}.damage-flash{z-index:1}.reload-toast{top:43%}.toast{top:18%;font-size:8px}.mobile-controls{padding-bottom:env(safe-area-inset-bottom)}.stick-zone{bottom:calc(16px + env(safe-area-inset-bottom));width:112px;height:112px;left:13px}.mobile-actions{bottom:calc(12px + env(safe-area-inset-bottom));right:11px;transform:scale(.88);transform-origin:bottom right}}
@media(max-height:500px) and (orientation:landscape){.topbar{height:44px}.left-stack,.right-stack{top:52px}.hud-bottom{bottom:8px}.vitals{width:170px}.controls-hint{bottom:90px}.briefing h1{font-size:52px;margin:15px 0}.brief-stats{margin:12px 0}.briefing{width:480px}.mobile-controls .stick-zone{width:92px;height:92px;bottom:5px}.mobile-actions{transform:scale(.72);bottom:5px}}

import * as THREE from './vendor/three.module.js';

const $ = id => document.getElementById(id);
const canvas = $('scene');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x46534c);
scene.fog = new THREE.FogExp2(0x46534c, 0.021);
const camera = new THREE.PerspectiveCamera(72, 1, 0.1, 160);
camera.position.set(0, 1.65, 8);
const renderer = new THREE.WebGLRenderer({canvas, antialias:true, powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.7));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;

scene.add(new THREE.HemisphereLight(0xb7c9bd, 0x32362b, 1.15));
const moon = new THREE.DirectionalLight(0xdce9dc, 2.3);
moon.position.set(-12, 24, 8); moon.castShadow = true;
moon.shadow.mapSize.set(1024,1024); moon.shadow.camera.left=-35; moon.shadow.camera.right=35; moon.shadow.camera.top=35; moon.shadow.camera.bottom=-35;
scene.add(moon);
const fill = new THREE.DirectionalLight(0xe4ae6e, 0.85); fill.position.set(9,8,-14); scene.add(fill);
const warm = new THREE.PointLight(0xff9a4f, 20, 17, 2); warm.position.set(-5,5,-12); scene.add(warm);
const cool = new THREE.PointLight(0x81a8a0, 12, 18, 2); cool.position.set(7,4,0); scene.add(cool);

const mat = (color, roughness=.82, metalness=0) => new THREE.MeshStandardMaterial({color,roughness,metalness});
const concrete=mat(0x50564e), darkConcrete=mat(0x343a35), rust=mat(0x55493b), steel=mat(0x303936,.5,.65), olive=mat(0x4c5542), sand=mat(0x8c8063), black=mat(0x151a19,.34,.7), gunMetal=mat(0x313a39,.27,.8), rubber=mat(0x181b19), wood=mat(0x604e3a), zombieSkin=mat(0x687263), rotten=mat(0x455448), shirt=mat(0x4b5147), blood=mat(0x542a24);
function box(parent, name, size, position, material, cast=true){const m=new THREE.Mesh(new THREE.BoxGeometry(...size),material);m.name=name;m.position.set(...position);m.castShadow=cast;m.receiveShadow=true;parent.add(m);return m;}

// Concrete yard, perimeter and the silhouettes of an abandoned industrial outpost.
const ground= new THREE.Mesh(new THREE.PlaneGeometry(180,180),mat(0x343b37));ground.rotation.x=-Math.PI/2;ground.position.y=-.04;ground.receiveShadow=true;scene.add(ground);
const road=new THREE.Mesh(new THREE.PlaneGeometry(8,130),mat(0x454b46));road.rotation.x=-Math.PI/2;road.position.set(0,.002,-30);scene.add(road);
for(let i=-5;i<24;i++){const seam=box(scene,'road seam',[.04,.012,.09],[0,.008,-i*5],mat(0x676c64),false);seam.position.x=0;}
// road center broken markings
for(let i=0;i<13;i++)box(scene,'lane dash',[.12,.015,1.5],[0,.014,-i*8-2],mat(0x99937a),false);
// distant blockout silhouettes
for(const [x,z,w,h,d,c] of [[-20,-30,13,16,14,0x535b51],[19,-37,17,20,19,0x434d48],[-31,-58,17,23,19,0x48524d],[31,-62,21,19,15,0x53564d],[-12,-82,22,25,18,0x4a514b],[12,-93,25,30,18,0x464d48]]){
 const b=box(scene,'warehouse',[w,h,d],[x,h/2-0.1,z],mat(c),true);b.castShadow=true;
 for(let yy=3;yy<h-2;yy+=4) box(scene,'window',[w*.82,.12,.08],[x,yy,z+d/2+.05],mat(0x242d29),false);
}
// containers, jersey barriers, pallets, crates, drums, fence posts
for(const [x,z,w,h,d,color] of [[-7,-11,5,3.8,2.4,0x59665b],[8,-18,6,4,2.5,0x714f3d],[-12,-28,6,4,2.5,0x59645b],[13,-36,5,3.8,2.4,0x665342]]){
 const c=box(scene,'shipping container',[w,h,d],[x,h/2,z],mat(color,.7,.25));
 for(let xx=-w/2+.25;xx<w/2;xx+=.45)box(scene,'container rib',[.045,h*.93,.04],[x+xx,h/2,z+d/2+.025],steel,false);
 box(scene,'container top rail',[w,.12,d],[x,h-.04,z],steel,false);
}
for(let i=0;i<8;i++){
 const x=(i%2?1:-1)*(5.7+(i%3)*1.6),z=-5-Math.floor(i/2)*9;
 const b=box(scene,'cargo crate',[1.1+(i%3)*.35,1.05,.95],[x,.53,z],i%2?wood:olive);
 for(let yy=.14;yy<1;yy+=.3)box(scene,'crate slat',[1.12+(i%3)*.35,.035,.98],[x,.53-1.05/2+yy,z],sand,false);
}
for(let i=0;i<9;i++){
 let x=-15+i*3.7;
 const post=box(scene,'fence post',[.12,2.5,.12],[x,1.25,-22],steel);
 for(let y=.8;y<2.6;y+=.55)box(scene,'fence wire',[3.65,.025,.025],[x+1.82,y,-22],steel,false);
}
for(const [x,z] of [[-5,-7],[6,-24],[-14,-42],[11,-48]]){
 const barrel=new THREE.Mesh(new THREE.CylinderGeometry(.42,.42,1.2,12),mat(0x55574d,.55,.3));barrel.position.set(x,.6,z);barrel.castShadow=true;scene.add(barrel);
 box(scene,'barrel band',[.87,.09,.87],[x,.43,z],steel,false);
}
// scattered weeds and debris
for(let i=0;i<90;i++){
 const x=(Math.random()-.5)*70,z=-Math.random()*90;
 if(Math.abs(x)<4)continue;
 const weed=new THREE.Mesh(new THREE.ConeGeometry(.035+Math.random()*.05,.2+Math.random()*.45,3),mat(i%2?0x52604a:0x626246));weed.position.set(x,.12,z);weed.rotation.z=(Math.random()-.5)*.8;scene.add(weed);
}
// overhead lamps in the yard
